head.script:
scwin.market = $c.session.getUserInfo("market");

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — search 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.searchIsurCode(acb_isurCd, ibx_isurCdNm);

        let ToDay = $c.date.getServerDateTime();
        cal_EDate.setValue(ToDay);
        cal_SDate.setValue($c.date.addMonth(ToDay, -3));

        if (scwin.market === '1' || scwin.market==='2' || scwin.market==='6') {
            rdo_MKT_ID.setValue(scwin.market);
            rdo_MKT_ID.setDisabled(true);
        } else{
            rdo_MKT_ID.setValue("9");
            rdo_MKT_ID.setDisabled(false);
        }

        // 날짜 포맷 검증 추가
        $c.date.compareFromToDate(cal_SDate, cal_EDate, ["조회 시작일자", "조회 종료일자"], "yyyyMMdd");

        // 해당 그룹 안의 컴포넌트에서 엔터키가 발생하면 해당 컴포넌트의 값을 DataCollection에 저장하고 objFunc 함수를 실행한다.
        $c.win.setEnterKeyEvent(tbl_search, scwin.btn_Search_onclick);

        // 검색조건으로 목록 조회
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07242.onpageload" });
    }
}

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 검색버튼 클릭 이벤트 — 「조회」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function (e) {
    try {
        if(!scwin.fnDateCheck()) return;

        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07242.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_isurCd_onclick
 * @description 회사코드 검색버튼 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_isurCd_onclick = function (e) {
    try {
        $c.cm.isurcdSearch(acb_isurCd, ibx_isurCdNm);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07242.btn_isurCd_onclick" });
    }
};

/**
 * @method
 * @name sbx_PeriodTp_onviewchange
 * @description 기간선택 변경 이벤트
 * @param {Object} info 이벤트 정보 객체
 * @returns {void}
 * @hidden N
 */
scwin.sbx_PeriodTp_onviewchange = function (info) {
    try {
        let selVal = info.newValue;

        if($c.util.isEmpty(selVal)) {
            cal_SDate.setValue("");
            cal_EDate.setValue("");
        } else {
            $c.stf.setFromToDate(selVal, cal_SDate, cal_EDate);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07242.sbx_PeriodTp_onviewchange" });
    }
};

/**
 * @method
 * @name btn_excel_onclick
 * @description 엑셀다운로드
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_excel_onclick = function(e) {
    try {
        if (grd_List.getRowCount() <= 0) {
            $c.win.alert("조회된 데이터가 없습니다.");
            return;
        }

        // grd_comList.GridToExcel("요약재무정보", "", "2"); //엑셀 다운로드
        $c.data.downloadGridViewExcel(grd_List, {fileName: "신규상장 기업분석보고서 관리", sheetName: "신규상장 기업분석보고서 관리"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07242.btn_excel_onclick" });
    }
};

/**
 * @method
 * @name grd_List_oncelldblclick
 * @description 팝업호출
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    try {
            if(columnId==='contnTitle'){
                if(dlt_irCeoList.getCellData(rowIndex, "gubun") === "1"){				// 업로드(제출)
                    scwin.forncomAnlrptDtlOpen(rowIndex);
                } else if(dlt_irCeoList.getCellData(rowIndex, "gubun") === "2"){	// 접수(처리)

                    scwin.inputDetailPopup("R");

                    // fn_setId(row);
                    // frame.CreateDialogFrame("gform", "/lstinvstg/ULDSTF07245.gfm", "신규상장 기업분석보고서/사업모델 평가보고서 및 기업 계속성 보고서 수정" ,200, 100, 750, 590, "window" );
                    // fn_list_sync();
                }
            }  else if (columnId === "comNm") {
                // fn_PopupCorpInfo();
            } else if(columnId === 'listProcsStatNm'){
                if( dlt_irCeoList.getCellData(rowIndex, "gubun") === "1"){				// 업로드(제출)
                        if ("34" === dlt_irCeoList.getCellData(rowIndex, 'listProcsStatCd') ){

                        // 수정요청 리스트 팝업창
                        scwin.modRequestListOpen(rowIndex);
                        }
                } else {	// 접수(처리)
                    $c.win.alert("해당건은  업로드(제출)인 경우에 한하여 승인여부가 가능합니다.");
                        return;
                }
            }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07242.grd_List_oncelldblclick" });
    }
};

/**
 * @method
 * @name btn_input_onclick
 * @description 입력 — 「입력」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_input_onclick = function () {
    try {
        scwin.inputDetailPopup("C");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07242.btn_input_onclick" });
    }
}

/**
 * @method
 * @name ibx_wrt_inst_nm_onkeydown
 * @description ibx_wrt_inst_nm 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ibx_wrt_inst_nm_onkeydown = async function (e) {
    try {
            // 엔터입력
        if (window.event.keyCode === 13) {
            await scwin.search();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07242.ibx_wrt_inst_nm_onkeydown" });
    }
};

/**
 * @method
 * @name ibx_Title_onviewchange
 * @description 제목 엔터입력
 * @param {Object} info 이벤트 정보 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ibx_Title_onviewchange = async function (info) {
    try {
        if(info) await scwin.btn_Search_onclick();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07242.ibx_Title_onviewchange" });
    }
};

/**
 * @method
 * @name ibx_wrt_inst_nm_onviewchange
 * @description 작성기관 엔터입력
 * @param {Object} info 이벤트 정보 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ibx_wrt_inst_nm_onviewchange = async function (info) {
    try {
        if(info) await scwin.btn_Search_onclick();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07242.ibx_wrt_inst_nm_onviewchange" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description 검색조건으로 목록 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {

    let vKosdaq_Bbs_Tp_Cd_1 = '';
    let vKosdaq_Bbs_Tp_Cd_2 = '';
    if (sbx_Kosdaq_Bbs_Tp_Cd.getValue()  === '12') {
        vKosdaq_Bbs_Tp_Cd_1 = '170' ;
    } else {
        vKosdaq_Bbs_Tp_Cd_1 = sbx_Kosdaq_Bbs_Tp_Cd.getValue();
    }

    if (sbx_Kosdaq_Bbs_Tp_Cd.getValue()  === '180') {
        vKosdaq_Bbs_Tp_Cd_2 = '13' ;
    } else {
        vKosdaq_Bbs_Tp_Cd_2 = sbx_Kosdaq_Bbs_Tp_Cd.getValue();
    }

    dma_searchReq.set("kosdaqBbsTpCd", vKosdaq_Bbs_Tp_Cd_1);
    dma_searchReq.set("kosdaqBbsTpCd2", vKosdaq_Bbs_Tp_Cd_2);

    const sbmOptions = {
        id : "sbm_irCeoList",
        action : "/api/listing/lstproc/frgn-com-anl-rpt/select-list",
        method : "get",
        ref : "dma_searchReq",
        target : "dlt_irCeoList=body",
        gridview : "grd_List",
        isProcessMsg : true
    };

    const res = await $c.sbm.executeDynamic(sbmOptions);

    txtl_page.setValue(dlt_irCeoList.getRowCount());
}

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name customToNm1
 * @description 코드를 명으로
 * @param {*} data 셀 값(원본 데이터)
 * @returns {*} 결과 값
 * @hidden N
 */
scwin.customToNm1 =  function (data) {

    return data === 'Y' ? '업로드(제출)' : '접수(처리)'

}

/**
 * @method
 * @name fnDateCheck
 * @description 검색조건 내 시작일, 종료일 기간 체크
 * @returns {*} 결과 값
 * @hidden N
 */
scwin.fnDateCheck = function() {    // scwin.dateCheck()
    let eDate = cal_EDate.getValue();
    let sDate = cal_SDate.getValue();
    let rtnVal = true;

    let diffDays = $c.date.diffDate(sDate, eDate);

    if(diffDays < 0)
    {
        $c.win.alert("[조회기간 시작일은 종료일보다 작아야 합니다.] 다시 입력해주세요");

        dma_searchReq.set("startDate", scwin.tDay);
        dma_searchReq.set("endDate", scwin.tDay);

        rtnVal = false;
    }

    return rtnVal;
}

/**
 * @method
 * @name modRequestListOpen
 * @description 신규상장 기업분석보고서/사업모델 평가보고서 및 기업 계속성 보고서 수정요청 리스트(팝업)
 * @param {*} pRow pRow
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.modRequestListOpen = async function(pRow) {

    let url = "/ui/lstproc/ULDSTF07243.xml";
    let popTitle = "신규상장 기업분석보고서/사업모델 평가보고서 및 기업 계속성 보고서 수정요청 리스트";

    const opts = {
        id: "ULDSTF07243",
        popupName: popTitle,
        width: 1200,
        height: 430,
        frameModal: "top",
    };

    const popData = dlt_irCeoList.getRowJSON(pRow);
    const res =  await $c.win.openPopup(url, opts, popData);
    if(res === "success") {
        await scwin.search();
    }

};

/**
 * @method
 * @name forncomAnlrptDtlOpen
 * @description 사업모델 평가보고서 및 기업 계속성 보고서 상세(팝업)
 * @param {*} pRow pRow
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.forncomAnlrptDtlOpen = async function(pRow) {

    let url = "/ui/lstproc/ULDSTF07244.xml";
    let popTitle = "사업모델 평가보고서 및 기업 계속성 보고서 상세";

    const opts = {
        id: "ULDSTF07244",
        popupName: popTitle,
        width: 1100,
        height: 520,
        frameModal: "top",
    };

    const popData = dlt_irCeoList.getRowJSON(pRow);
    const res = await $c.win.openPopup(url, opts, popData);

    if(res === "success") {
        await scwin.search();
    }

};

/**
 * @method
 * @name inputDetailPopup
 * @description 입력팝업상세 호출
 * @param {String|Number} val 값
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.inputDetailPopup = async function (val) {

    let flagVal = val
    let contnIdVal = ""
    if(flagVal === "R") {
        contnIdVal = dlt_irCeoList.getCellData(dlt_irCeoList.getRowPosition(), "bzProcsNo");
    }
    let url = "/ui/lstproc/ULDSTF07245.xml";
    let popTitle = "신규상장 기업분석보고서/사업모델 평가보고서 및 기업 계속성 보고서 등록";
    const opts = {
        id: "ULDSTF07245",
        popupName: popTitle,
        width: 1200,
        height: 1000,
        frameModal: "top",
    };

    const popData = { flag : flagVal, contnId : contnIdVal};

    const res = await $c.win.openPopup(url, opts, popData);
    if( res === "success") {
        scwin.search();
    }

};
